import sys
import json
import csv
import os
import datetime

def parse_date(val):
    val = val.strip()
    if not val:
        return None
    if val.isdigit():
        serial = int(val)
        # Excel leap year bug: 1900 is treated as a leap year.
        if serial < 60:
            d = datetime.date(1899, 12, 31) + datetime.timedelta(days=serial)
        else:
            d = datetime.date(1899, 12, 30) + datetime.timedelta(days=serial)
        return d.strftime("%Y-%m-%d")

    # Fallback for standard date formats
    try:
        return datetime.datetime.strptime(val, "%Y-%m-%d").strftime("%Y-%m-%d")
    except ValueError:
        pass
    try:
        return datetime.datetime.strptime(val, "%m/%d/%Y").strftime("%Y-%m-%d")
    except ValueError:
        pass

    return val

def parse_amount(val):
    val = val.strip()
    if not val:
        return None
    val = val.replace(',', '').replace('$', '')
    return val

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    lca_path = os.path.join(packet_dir, 'lca_disclosure.csv')

