            for row in reader:
                entity = row.get('CASE_NUMBER', '').strip()
                if not entity:
                    continue

                if entity not in entity_facts:
                    entity_facts[entity] = {
                        'offered wage': set(),
                        'prevailing wage': set(),
                        'begin date': set(),
                        'end date': set()
                    }

                ow = parse_amount(row.get('WAGE_RATE_OF_PAY_FROM', ''))
                if ow:
                    entity_facts[entity]['offered wage'].add((ow, 'lca_disclosure'))

                pw = parse_amount(row.get('PREVAILING_WAGE', ''))
                if pw:
                    entity_facts[entity]['prevailing wage'].add((pw, 'lca_disclosure'))

                bd = parse_date(row.get('BEGIN_DATE', ''))
                if bd:
                    entity_facts[entity]['begin date'].add((bd, 'lca_disclosure'))

